const CAJA={"cats": {"participar-y-repasar": ["Participar y repasar", "<path d=\"M9 9a3 3 0 1 1 4.2 2.7c-.8.4-1.2 1-1.2 1.8V14\"/><circle cx=\"12\" cy=\"17.5\" r=\".6\"/><circle cx=\"12\" cy=\"12\" r=\"9\"/>"], "crear-y-presentar": ["Crear y presentar", "<path d=\"M4 20h4L19 9l-4-4L4 16z\"/><path d=\"m13.5 6.5 4 4\"/>"], "colaborar-y-organizar": ["Colaborar y organizar", "<circle cx=\"8\" cy=\"9\" r=\"3\"/><circle cx=\"16\" cy=\"9\" r=\"3\"/><path d=\"M3 19c.8-3 2.8-4.5 5-4.5s4.2 1.5 5 4.5M11 19c.8-3 2.8-4.5 5-4.5s4.2 1.5 5 4.5\"/>"], "explorar-por-materias": ["Explorar por materias", "<path d=\"M4 5.5C6 4.5 9 4.5 12 6c3-1.5 6-1.5 8-.5V19c-2-1-5-1-8 .5-3-1.5-6-1.5-8-.5z\"/><path d=\"M12 6v13.5\"/>"], "programacion-y-diseno-3d": ["Programación y diseño 3D", "<path d=\"m8 8-4 4 4 4M16 8l4 4-4 4M13.5 5l-3 14\"/>"], "inteligencia-artificial": ["Inteligencia artificial", "<path d=\"M12 3v3M12 18v3M3 12h3M18 12h3\"/><rect x=\"7\" y=\"7\" width=\"10\" height=\"10\" rx=\"2.5\"/><path d=\"M10 12h4M12 10v4\"/>"], "evaluacion-y-seguimiento": ["Evaluación y seguimiento", "<path d=\"M9 4h6v3H9z\"/><path d=\"M8 5.5H6.5A1.5 1.5 0 0 0 5 7v12.5A1.5 1.5 0 0 0 6.5 21h11a1.5 1.5 0 0 0 1.5-1.5V7a1.5 1.5 0 0 0-1.5-1.5H16\"/><path d=\"m9 14 2 2 4-4\"/>"], "gestion-del-aula": ["Gestión del aula y familias", "<rect x=\"4\" y=\"5\" width=\"16\" height=\"15\" rx=\"2\"/><path d=\"M4 9.5h16M9 3v4M15 3v4\"/>"], "aulas-virtuales": ["Aulas virtuales", "<rect x=\"3\" y=\"4.5\" width=\"18\" height=\"12\" rx=\"2\"/><path d=\"M8 20h8M12 16.5V20\"/>"], "bancos-de-recursos": ["Bancos de recursos e imágenes", "<rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2.5\"/><circle cx=\"9.5\" cy=\"9.5\" r=\"1.8\"/><path d=\"m20 15-4.5-4.5L6 20\"/>"]}, "t": {"kahoot": ["participar-y-repasar", ["I", "P", "S"], 1, "Cuestionarios y juegos", "Activar ideas previas Repasar antes de un examen Competir por equipos Comprobar qué se ha entendido Kahoot! es una plataforma de cuestionarios en forma de concurso. El docente proyecta las preguntas y el alumnado responde desde su dispositivo con un PIN, sin registrarse. También tiene un modo sin dispositivos. Gana puntos quien acierta antes. Al terminar, el docente ve un informe con los aciertos de cada pregunta y de cada alumno. En un mismo kahoot se combinan preguntas de tipo test, de ordenar o de escribir la respuesta. También se puede editar uno ya hecho. "], "wayground": ["participar-y-repasar", ["P", "S"], 1, "Cuestionarios y juegos", "Repasar de forma individual Mandar tareas para casa Adaptar la dificultad Seguir el progreso de cada alumno Wayground, que antes se llamaba Quizizz, es una herramienta de cuestionarios y lecciones interactivas. A diferencia de un concurso en directo, cada alumno avanza a su ritmo, en clase o en casa, con ayudas como la lectura en voz alta. El docente recibe un informe detallado por alumno y por pregunta. Wayground es el nuevo nombre de Quizizz"], "wooclap": ["participar-y-repasar", ["S"], 1, "Cuestionarios y juegos", "Hacer una lluvia de ideas Comprobar la comprensión a mitad de clase Abrir un debate Cerrar la sesión con una reflexión Wooclap convierte la explicación en una conversación. Mientras el docente presenta, el alumnado responde con su móvil u ordenador a encuestas, nubes de palabras, preguntas abiertas o actividades de ordenar y señalar en una imagen. Las respuestas aparecen al momento en la pantalla de clase. Así opina todo el grupo y no solo quien levanta la mano. Puedes parar, comentar los resultados y decidir si hace falta volver atrás. "], "mentimeter": ["participar-y-repasar", ["S"], 1, "Cuestionarios y juegos", "Lanzar encuestas Recoger preguntas anónimas Hacer nubes de palabras Valorar una exposición Mentimeter es una herramienta de presentaciones interactivas. El alumnado vota y responde de forma anónima desde su dispositivo con un código y los resultados se muestran al momento en gráficos o nubes de palabras. El anonimato ayuda a que participe quien no suele levantar la mano. Las preguntas pueden ser de elección, de escala o abiertas. También hay concursos. Con lo que sale en pantalla puedes abrir un debate. "], "plickers": ["participar-y-repasar", ["I", "P", "S"], 1, "Cuestionarios y juegos", "Evaluar en aulas sin ordenadores Comprobar ideas previas Registrar respuestas por alumno Hacer preguntas de cierre Plickers permite hacer preguntas rápidas a toda la clase sin que el alumnado use dispositivos. Cada alumno gira su tarjeta de papel según la respuesta que elige. El docente las escanea todas con su móvil y obtiene los resultados al instante. La pregunta se lee o se proyecta y todos levantan su tarjeta a la vez. Los resultados sirven para repasar en el momento lo que ha fallado. "], "blooket": ["participar-y-repasar", ["S"], 1, "Cuestionarios y juegos", "Gamificar el repaso Competir por equipos Repasar vocabulario Mandar tareas para casa Blooket propone cuestionarios con distintos modos de juego, como carreras, torres o tiendas. El alumnado responde preguntas para avanzar en el juego, en directo en clase o como tarea, de forma individual o por equipos. Funciona muy bien con los primeros cursos. El docente busca un conjunto de preguntas ya hecho o crea el suyo y después elige el modo de juego. Al terminar, un informe ayuda a ver qué conviene volver a explicar. "], "wordwall": ["participar-y-repasar", ["I", "P", "S"], 1, "Cuestionarios y juegos", "Crear juegos de repaso Preparar fichas imprimibles Asignar tareas a su ritmo Seguir los resultados Wordwall sirve para crear actividades interactivas e imprimibles a partir de plantillas. El docente prepara el contenido y el alumnado juega en su propio dispositivo. Se elige una plantilla, como un cuestionario o un crucigrama. Después se escribe el contenido. Con un clic se puede pasar a otra sin copiarlo de nuevo. También sirve para jugar por turnos en la pizarra. El plan Básico de Wordwall es gratuito y permite crear hasta 3 actividades y el Estándar cuesta 5 € al mes o 40 € al año"], "educaplay": ["participar-y-repasar", ["I", "P", "S"], 1, "Cuestionarios y juegos", "Crear actividades autocorregibles Practicar con mapas Repasar vocabulario Reutilizar actividades de otros docentes Educaplay sirve para crear y compartir actividades interactivas: crucigramas, sopas de letras, mapas interactivos, relacionar o completar frases. El alumnado las resuelve con un enlace y se corrigen solas. Tiene además un gran banco de actividades creadas por otros docentes. También hay test, rosco de palabras, memory o dictado. El docente elige el tipo, escribe el contenido y prueba la actividad antes de pasarla. "], "edpuzzle": ["participar-y-repasar", ["P", "S"], 1, "Cuestionarios y juegos", "Trabajar con aula invertida Comprobar la comprensión de un vídeo Repasar una explicación Atender a distintos ritmos Edpuzzle convierte cualquier vídeo en una lección interactiva. El docente recorta el vídeo y añade preguntas o notas que lo detienen en momentos clave. El alumnado lo ve a su ritmo y responde. El docente puede comprobar quién lo ha visto y qué ha contestado. El vídeo puede ser uno propio o una lección ya hecha de su biblioteca, creada por otros docentes. Así el docente sabe qué parte hay que volver a explicar. "], "nearpod": ["participar-y-repasar", ["P", "S"], 1, "Cuestionarios y juegos", "Dar una lección interactiva Comprobar la comprensión en directo Dibujar o señalar sobre imágenes Hacer visitas virtuales Nearpod sincroniza una presentación con los dispositivos del alumnado. Entre diapositiva y diapositiva se intercalan preguntas, dibujos, encuestas o visitas virtuales. El docente ve en directo las respuestas de cada alumno. Puedes partir de una presentación, un PDF o un vídeo que ya tengas y añadirle las actividades. En una sesión en directo, el docente marca el ritmo. Al terminar queda un informe. "], "decktoys": ["participar-y-repasar", ["S"], 1, "Cuestionarios y juegos", "Crear itinerarios por niveles Gamificar una unidad Atender a distintos ritmos Trabajar de forma autónoma Deck.Toys organiza las actividades como un recorrido o un tablero de juego. Cada parada puede ser una diapositiva, un vídeo o un ejercicio y las siguientes se desbloquean al completar las anteriores, de modo que cada alumno sigue su propio camino. El docente monta el mapa y une las actividades con caminos, por ejemplo uno de refuerzo y otro de ampliación. El alumnado también puede responder con texto o dibujos. "], "socrative": ["participar-y-repasar", ["S"], 1, "Cuestionarios y juegos", "Comprobar lo aprendido Evaluar al momento Tener un informe por alumno Preguntar al cerrar la clase Socrative sirve para lanzar cuestionarios y preguntas rápidas que se corrigen solos. El docente prepara las preguntas, abre la actividad en su sala y sigue las respuestas en directo. Al terminar tiene un informe con lo que ha contestado cada alumno. Es más sobria que un concurso: está pensada para comprobar qué se ha entendido. Los cuestionarios se pueden importar desde una hoja de Excel. "], "quizlet": ["participar-y-repasar", ["S"], 1, "Cuestionarios y juegos", "Memorizar vocabulario Repasar definiciones Competir por equipos Estudiar a su ritmo Quizlet sirve para estudiar con unidades de tarjetas: un término por un lado y su definición o una imagen por el otro. Con la misma unidad se practica de varias formas, con preguntas, actividades y diagramas. En Quizlet Live el docente lanza un juego con una unidad y la clase compite por equipos desde sus dispositivos. Además, hay muchas unidades ya hechas por otros usuarios para aprovecharlas. "], "jeopardylabs": ["participar-y-repasar", ["S"], 0, "Cuestionarios y juegos", "Repasar por equipos Preparar un examen Organizar un concurso Trabajar por categorías JeopardyLabs sirve para crear un tablero de preguntas por categorías al estilo del concurso Jeopardy. Cada casilla tiene un valor en puntos. El docente lo proyecta y los equipos eligen por turnos la categoría y el valor de su pregunta. Se puede crear sin cuenta: cada tablero se guarda con una contraseña para editarlo después. La web está en inglés, pero las preguntas se escriben en cualquier idioma. "], "cerebriti": ["participar-y-repasar", ["S"], 1, "Cuestionarios y juegos", "Repasar jugando Localizar en mapas mudos Retar a la clase Atender distintos ritmos Cerebriti es una plataforma española de juegos educativos que crea su propia comunidad de usuarios. Hay juegos de todas las materias y cursos en diez formatos, como tests, mapas mudos, parejas o rankings. El alumnado busca un juego del tema que se está estudiando y lo juega en el navegador. El docente puede proponer uno concreto con su enlace o dejar que cada uno busque el suyo. "], "gcompris": ["participar-y-repasar", ["I", "P"], 1, "Cuestionarios y juegos", "Reconocer letras y números Practicar el conteo Trabajar colores y formas Jugar con la lógica GCompris es un programa con más de cien actividades educativas para niños de 2 a 10 años: letras, números, colores, el reloj o la lógica. Es software libre y lo desarrolla la comunidad KDE. Las actividades están agrupadas por temas: lectura, aritmética, ciencia, geografía o juegos como el ajedrez y las tres en raya. También hay ejercicios para aprender a usar el ratón y el teclado. "], "artsculture": ["explorar-por-materias", ["I", "P", "S"], 1, "Geografía e Historia", "Analizar obras de arte Hacer visitas virtuales Investigar con fuentes fiables Repasar estilos artísticos Google Arts & Culture reúne las colecciones de miles de museos y archivos de todo el mundo. Permite ver obras en altísima resolución, recorrer museos con visitas virtuales y leer historias preparadas por los propios museos. Incluye también juegos y experimentos sobre arte. En clase cada alumno puede elegir una obra, acercarse a un detalle y explicar lo que ve. También se puede proyectar una historia y leerla entre todos. "], "visitas": ["explorar-por-materias", ["I", "P", "S"], 1, "Geografía e Historia", "Visitar museos y monumentos Preparar una salida Analizar un espacio histórico Motivar al empezar un tema Las visitas virtuales en 360° son recorridos por dentro de museos y monumentos que se hacen desde el aula, en la web de cada lugar. Son un buen recurso para conocer un espacio antes de estudiarlo o para visitar lugares a los que no se puede ir de excursión. Se puede proyectar el recorrido y hacerlo entre todos o dejar que cada grupo explore una sala. Funciona mejor con una tarea: localizar una obra o dibujar un plano. "], "earth": ["explorar-por-materias", ["I", "P", "S"], 1, "Geografía e Historia", "Explorar paisajes Comparar cambios en el tiempo Crear rutas y proyectos Localizar lugares estudiados Google Earth es un globo terráqueo en 3D con imágenes de satélite de todo el planeta. Permite viajar a cualquier lugar, ver edificios y relieve en tres dimensiones, comparar imágenes de distintos años y crear proyectos propios con mapas, fotos y texto. Los proyectos se montan con puntos, textos e imágenes colocados sobre el globo. Así el alumnado cuenta una historia en su lugar real y la presenta en clase. "], "geacron": ["explorar-por-materias", ["S"], 1, "Geografía e Historia", "Ver la evolución de las fronteras Situar acontecimientos en el mapa Comparar épocas Explicar con apoyo visual GeaCron es un atlas histórico interactivo. Al mover una línea del tiempo, el mapa del mundo cambia año a año y muestra cómo evolucionan los estados, los imperios y sus fronteras desde la Antigüedad hasta hoy. Se elige un año, se acerca el mapa y se ve quién gobernaba cada territorio. En clase se puede proyectar una fecha y pedir que expliquen qué ha cambiado respecto a otra. También tiene cronologías para ordenar hechos. "], "rah": ["explorar-por-materias", ["S"], 1, "Geografía e Historia", "Buscar biografías fiables Investigar sobre la historia local Contrastar información Enseñar a citar fuentes Historia Hispánica es el portal de la Real Academia de la Historia. Ofrece miles de biografías escritas por especialistas y un mapa interactivo para buscar personajes por lugar o época. Es una fuente fiable para trabajos de investigación. Se busca por quién, cuándo, dónde y qué, con una búsqueda guiada o combinando criterios. Al pulsar un punto del mapa salen los personajes que nacieron o murieron allí. "], "delmundo": ["explorar-por-materias", ["S"], 1, "Geografía e Historia", "Consultar datos de países Comparar con clasificaciones Practicar con mapas Repasar jugando DelMundo es una enciclopedia digital y atlas geográfico. Reúne datos e ilustraciones sobre relieve, clima, aguas y población, clasificaciones del planeta y juegos interactivos para poner a prueba lo aprendido. Hay mapas políticos y físicos del mundo, de los continentes y de varios países. El alumnado busca un dato, lo sitúa en el mapa y lo comprueba después en un juego de banderas o en un trivial. "], "kgeography": ["explorar-por-materias", ["P", "S"], 1, "Geografía e Historia", "Aprender mapas políticos Repasar capitales y banderas Practicar de forma autónoma Hacer pequeñas pruebas KGeography es un programa libre para aprender geografía jugando. Propone ejercicios de mapas para localizar divisiones políticas, capitales y banderas de distintos países y regiones. Se instala en el ordenador. Unas veces aparece el nombre de una provincia o de un país y hay que pulsarlo en el mapa. Otras se ve una bandera o una capital y hay que decir a qué lugar corresponde. "], "ancientearth": ["explorar-por-materias", ["P", "S"], 1, "Geografía e Historia", "Explicar la tectónica de placas Visualizar el tiempo geológico Relacionar Geografía y Ciencias Motivar al empezar un tema Ancient Earth es un globo interactivo que muestra la posición de los continentes en distintos momentos de la historia de la Tierra. Se puede buscar una ciudad actual y ver dónde estaba hace cientos de millones de años. Se elige una época en una lista y el globo cambia. También se puede mostrar el ecuador o las fronteras actuales para orientarse. En clase se buscan dos o tres fechas alejadas y el alumnado anota qué ha cambiado. "], "atlasign": ["explorar-por-materias", ["S"], 1, "Geografía e Historia", "Estudiar la geografía de España Leer e interpretar mapas Preparar la prueba de acceso Repasar vocabulario geográfico El Atlas Didáctico es un recurso educativo abierto del Instituto Geográfico Nacional. Reúne quince temas de geografía de España en cinco bloques, con una versión para ESO y otra para Bachillerato. Los temas se apoyan en mapas interactivos, multimedia y actividades. Cada tema se puede consultar en línea o descargar. El alumnado explora los mapas, lee y hace las actividades. Está pensado como complemento del libro de texto. "], "minecraftedu": ["crear-y-presentar", ["S"], 1, "Lo crea el alumnado", "Explorar civilizaciones Construir en equipo Resolver desafíos Aprender jugando Minecraft Education es la edición educativa del videojuego de construcción. Trae lecciones y mundos ya preparados por materias, como colecciones sobre el antiguo Egipto, la Primera Guerra Mundial o las ciudades y civilizaciones. El docente abre un mundo y comparte un código de cuatro imágenes para que la clase entre a la vez. Una vez dentro, exploran, resuelven desafíos y construyen en equipo. "], "canva": ["crear-y-presentar", ["P", "S"], 1, "Lo crea el alumnado", "Diseñar infografías y pósteres Hacer presentaciones Crear materiales de clase Trabajar en grupo Canva es una herramienta de diseño gráfico con miles de plantillas. Con la cuenta de Canva para Educación, el docente crea una clase e invita al alumnado, que puede diseñar infografías, pósteres, presentaciones, vídeos o documentos, también en grupo. Se parte de una plantilla o de una página en blanco y se colocan textos, imágenes y formas. Conviene dar antes el contenido y unas pautas para no perder tiempo con el diseño. "], "genially": ["crear-y-presentar", ["P", "S"], 1, "Lo crea el alumnado", "Crear presentaciones interactivas Diseñar juegos y escape rooms Hacer infografías Presentar trabajos del alumnado Genially sirve para crear contenidos interactivos: presentaciones, infografías, imágenes con puntos que se pueden pulsar, juegos y escape rooms. Tiene muchas plantillas y el resultado se comparte con un enlace o se inserta en el aula virtual. El alumnado pulsa en la pantalla y descubre textos, imágenes o preguntas en el orden que elige. También se puede proyectar en directo y lanzar preguntas a la clase. "], "bookcreator": ["crear-y-presentar", ["I", "P", "S"], 1, "Lo crea el alumnado", "Crear libros digitales Hacer cómics Montar un portfolio Reunir trabajos en un libro Book Creator permite crear libros digitales combinando texto, imágenes, dibujos, audio y vídeo. El docente crea una biblioteca a la que el alumnado se une para escribir sus libros. El resultado se puede leer en línea. El alumnado va añadiendo páginas, coloca los elementos donde quiere y puede grabar su voz desde el propio libro. El docente puede dejar comentarios en las páginas para que lo mejore. "], "sway": ["crear-y-presentar", ["S"], 1, "Lo crea el alumnado", "Hacer reportajes Presentar trabajos Crear un portfolio digital Publicar materiales de clase Sway es la herramienta de Microsoft para crear presentaciones que se leen como una página web. Se añaden textos, imágenes y vídeos y Sway los organiza con un diseño adaptado a cualquier pantalla. Funciona con la cuenta Microsoft del centro. El alumnado no diseña diapositiva a diapositiva, así que dedica más tiempo a redactar y a escoger las imágenes. El resultado se comparte con un enlace. "], "timetoast": ["crear-y-presentar", ["S"], 1, "Lo crea el alumnado", "Crear cronologías Ordenar acontecimientos Hacer biografías Comparar procesos en paralelo Timetoast sirve para crear líneas del tiempo interactivas. Cada acontecimiento lleva su fecha, una descripción y una imagen. El resultado se comparte con un enlace. La misma línea se ve en horizontal, en vertical o como una tabla. Los acontecimientos se pueden agrupar en franjas, por ejemplo política, economía y cultura. El alumnado tiene que elegir qué hechos entran y explicar cada uno con pocas palabras. "], "storymap": ["crear-y-presentar", ["S"], 1, "Lo crea el alumnado", "Contar rutas y viajes Explicar procesos sobre el territorio Presentar el patrimonio local Investigar en equipo StoryMap JS es una herramienta gratuita para contar historias sobre un mapa. Cada diapositiva corresponde a un lugar, con su texto y su imagen. El mapa se desplaza de un punto al siguiente mientras se avanza. El sitio se busca por su nombre o su dirección. También admite vídeos y audios de otras webs. En vez de un mapa, se puede recorrer una imagen grande, como un cuadro o un plano antiguo. StoryMap JS es una herramienta gratuita del Knight Lab para contar historias sobre un mapa"], "stopmotion": ["crear-y-presentar", ["I", "P", "S"], 1, "Lo crea el alumnado", "Animar procesos Contar historias Trabajar en equipo Explicar conceptos de forma creativa Stop Motion Studio es una aplicación para hacer animaciones foto a foto. Se fotografía cada pequeño movimiento de unos objetos, figuras o dibujos y la aplicación los une en un vídeo, al que se puede añadir sonido. Primero se planifica con un guion gráfico y se prepara la escena con papel, plastilina o lo que haya en clase. Al disparar, se ve la foto anterior para colocar bien las piezas. "], "chatterpix": ["crear-y-presentar", ["I", "P", "S"], 1, "Lo crea el alumnado", "Presentar personajes Practicar la expresión oral Resumir un tema Dar voz a obras y monumentos ChatterPix Kids es una aplicación para hacer hablar a una imagen. Se dibuja una boca sobre una foto o un dibujo y se graba la voz. La boca se mueve al ritmo del audio. Antes conviene escribir un guion corto y ensayarlo en voz alta. Después se puede decorar la imagen con pegatinas, marcos y filtros. El resultado se enseña a la clase. También ayuda a quien prefiere hablar sin salir en cámara. "], "tuxpaint": ["crear-y-presentar", ["I", "P"], 1, "Lo crea el alumnado", "Dibujar con el ratón o con el dedo Ilustrar cuentos y proyectos Iniciarse en el uso del ordenador Expresarse sin saber escribir Tux Paint es un programa de dibujo libre y gratuito para niños de 3 a 12 años. Combina pinceles, sellos y efectos con sonidos y una mascota que anima a quien dibuja. El lienzo tiene un tamaño fijo y no hay que poner nombre a los archivos, que se abren desde miniaturas. Tux, el pingüino de Linux, da pistas en la parte de abajo. El docente puede añadir más pinceles. "], "capcut": ["crear-y-presentar", ["S"], 1, "Lo crea el alumnado", "Editar vídeos Hacer vídeos explicativos Añadir subtítulos Presentar proyectos CapCut es un editor de vídeo para móvil y ordenador con plantillas, efectos y subtítulos automáticos. Permite montar vídeos cortos con un acabado cuidado sin conocimientos previos de edición. El alumnado ordena los clips en una línea de tiempo, corta lo que sobra y añade voz, texto o música. Conviene llegar con un guion breve y los planos ya grabados. Después queda montar, revisar los subtítulos y guardar el vídeo final. "], "clipchamp": ["crear-y-presentar", ["S"], 1, "Lo crea el alumnado", "Editar vídeos Grabar la pantalla Hacer tutoriales Presentar proyectos Clipchamp es el editor de vídeo de Microsoft. Funciona en el navegador, sin instalar nada. Permite montar vídeos, grabar la pantalla y la cámara a la vez y añadir textos y música. Se usa con la cuenta Microsoft del centro. El alumnado reúne los clips, los recorta y los ordena. También puede añadir subtítulos automáticos, que hay que repasar. Al final se exporta un archivo de vídeo para entregar o proyectar. "], "vocaroo": ["crear-y-presentar", ["I", "P", "S"], 1, "Lo crea el alumnado", "Grabar lecturas en voz alta Practicar la expresión oral Responder con audio Dar instrucciones habladas Vocaroo es la forma más sencilla de grabar un audio: se pulsa un botón, se graba con el micrófono y se obtiene un enlace para compartirlo. No hace falta registrarse ni instalar nada. El alumno lee, explica o responde, se escucha y repite si no le convence. Después entrega el enlace en el aula virtual. También puedes grabar tú un dictado. Para comprobar el avance, se pueden comparar dos grabaciones. "], "audacity": ["crear-y-presentar", ["S"], 1, "Lo crea el alumnado", "Grabar pódcasts Editar entrevistas Hacer programas de radio Trabajar la expresión oral Audacity es un programa libre y gratuito para grabar y editar audio. Permite cortar, unir varias pistas, ajustar el volumen, quitar ruido y añadir música o efectos. Se instala en el ordenador. Cada voz o sonido va en su pista. El alumnado escribe un guion, graba por partes, quita los errores y mezcla las voces. Al final se exporta un archivo de audio, por ejemplo en MP3, para escucharlo o compartirlo. Audacity es software libre y gratuito, con licencia GPL"], "zencastr": ["crear-y-presentar", ["I", "P", "S"], 1, "Materiales del docente", "Grabar pódcasts en grupo Hacer entrevistas a distancia Grabar debates Preparar materiales en audio Zencastr sirve para grabar un pódcast con varias personas que están en lugares distintos. Cada participante entra con un enlace desde su navegador y su voz se graba en una pista separada, lo que facilita la edición posterior. También graba vídeo. Dentro se puede limpiar el sonido, quitar pausas y sacar la transcripción. Conviene preparar antes un guion con los turnos. "], "suno": ["crear-y-presentar", ["P", "S"], 1, "Lo crea el alumnado", "Crear canciones para memorizar Trabajar la escritura con rima Motivar al empezar un tema Explorar estilos musicales Suno es una herramienta de inteligencia artificial que crea canciones. Se escribe la letra o se describe la idea y el estilo musical y la IA genera la canción completa con voz e instrumentos. En clase puede escribir la letra el grupo y dejar a la IA solo la música. Así hay que resumir el tema, buscar rimas y medir los versos. Después se escucha y se corrige lo que no encaja. "], "padlet": ["colaborar-y-organizar", ["I", "P", "S"], 1, "Trabajar en equipo", "Hacer una lluvia de ideas Realizar rutinas de pensamiento Debatir Trabajar de forma cooperativa Padlet es un muro digital compartido. El docente lo crea y el alumnado publica en él ideas, enlaces, imágenes, audios o vídeos, que se pueden ordenar en columnas, sobre un mapa o en una línea del tiempo. Se entra con un enlace o un código QR. Las publicaciones aparecen al momento, así que se puede ir comentando en clase lo que llega. Al terminar, el muro se presenta como diapositivas o se exporta a PDF. "], "mindomo": ["colaborar-y-organizar", ["S"], 1, "Trabajar en equipo", "Hacer esquemas Organizar ideas Planificar proyectos Estudiar con resúmenes visuales Mindomo sirve para crear mapas mentales, mapas conceptuales y esquemas. Varias personas pueden editar el mismo mapa a la vez y se pueden añadir imágenes, enlaces y notas a cada idea. El alumnado parte de una idea central, saca ramas y las ordena. Las mismas ideas se pueden ver como mapa, como esquema o como diagrama de Gantt, que coloca las tareas de un proyecto en el tiempo. "], "stormboard": ["colaborar-y-organizar", ["S"], 1, "Trabajar en equipo", "Hacer una lluvia de ideas Priorizar propuestas Organizar un proyecto Trabajar de forma cooperativa Stormboard es una pizarra digital compartida con notas adhesivas. El equipo añade ideas, las agrupa, las vota y las ordena para tomar decisiones. Puedes empezar con la pizarra en blanco o con una plantilla, por ejemplo un mapa mental o un mapa conceptual. Cada alumno escribe sus notas y todos ven las del resto. Al acabar, el trabajo se puede exportar como informe, hoja de cálculo o presentación. "], "loop": ["colaborar-y-organizar", ["S"], 1, "Trabajar en equipo", "Repartir tareas Organizar un proyecto Tomar notas en equipo Hacer actas de grupo Microsoft Loop es un espacio de trabajo compartido con listas de tareas, tablas y notas que se actualizan en tiempo real para todo el equipo. Funciona con la cuenta Microsoft del centro. Tiene tres partes: áreas de trabajo, páginas y componentes. El área reúne todo lo de un proyecto, la página es una hoja en blanco y los componentes son las piezas que se ponen en ella. En clase, cada grupo puede llevar ahí todo su trabajo. "], "trello": ["colaborar-y-organizar", ["S"], 1, "Trabajar en equipo", "Gestionar proyectos Repartir tareas y plazos Ver el avance del equipo Trabajar de forma cooperativa Trello organiza el trabajo en tableros con columnas, por ejemplo «pendiente», «en curso» y «hecho». Cada tarea es una tarjeta que se mueve de una columna a otra, con su responsable y su fecha. Cada equipo puede tener su tablero y revisarlo al empezar la sesión. De un vistazo se ve qué falta, quién lo hace y dónde se ha parado el trabajo. También sirve para coordinar a un departamento. "], "kialo": ["colaborar-y-organizar", ["S"], 1, "Trabajar en equipo", "Debatir por escrito Argumentar a favor y en contra Preparar un texto argumentativo Trabajar el pensamiento crítico Kialo Edu es una plataforma para debatir por escrito en clase. Cada debate se organiza como un mapa de argumentos: el alumnado añade ideas a favor y en contra bajo los puntos de sus compañeros. Todo parte de una tesis inicial. Cada argumento puede recibir a su vez razones a favor y en contra, así que se ve de dónde sale cada idea. Toda la clase escribe a la vez y el debate queda guardado para repasarlo o evaluarlo. Kialo Edu dice que es gratuita y que siempre lo será, sin anuncios"], "geogebra": ["explorar-por-materias", ["P", "S"], 1, "Ciencias y Matemáticas", "Explorar funciones Trabajar geometría dinámica Analizar datos Reutilizar actividades de otros docentes GeoGebra es una aplicación de matemáticas dinámicas que une geometría, álgebra, funciones, estadística y cálculo. Al mover un punto o cambiar un valor, todo se actualiza al momento. Tiene además miles de actividades creadas por docentes. El alumnado construye una figura o una gráfica, la mueve y comprueba qué se mantiene y qué cambia. También se pueden ver cuerpos y superficies en 3D. "], "desmos": ["explorar-por-materias", ["S"], 1, "Ciencias y Matemáticas", "Representar funciones Explorar parámetros Comprobar resultados Analizar datos Desmos reúne calculadoras gráfica, geométrica y científica en línea. Es muy fácil de usar: se escriben las expresiones y aparecen sus gráficas, que cambian al mover los parámetros. El alumnado escribe una función, ve qué pasa al cambiar un valor y explica por qué ocurre. También se puede partir de una tabla: se escriben los datos, aparecen los puntos y se busca la expresión que mejor encaja. "], "phet": ["explorar-por-materias", ["P", "S"], 1, "Ciencias y Matemáticas", "Hacer un laboratorio virtual Visualizar conceptos abstractos Aprender por descubrimiento Comprobar hipótesis PhET, de la Universidad de Colorado, ofrece simulaciones interactivas y gratuitas de física, química, biología y matemáticas, traducidas al español. El alumnado manipula variables y observa qué ocurre, como en un laboratorio. Se puede proyectar y preguntar antes de tocar nada qué creen que pasará. Luego cada pareja lo comprueba, anota los datos y saca una conclusión. PhET ofrece simulaciones gratuitas en línea de física, química, biología, ciencias de la tierra y matemáticas"], "gizmos": ["explorar-por-materias", ["P", "S"], 1, "Ciencias y Matemáticas", "Simular experimentos Trabajar en clases bilingües Visualizar conceptos Aprender por descubrimiento Gizmos es una colección de simulaciones de ciencias y matemáticas, en inglés, con guías de actividad para cada una. Algunas son gratuitas y el resto requiere suscripción. El alumnado cambia una variable, observa qué ocurre y anota los resultados, como en un laboratorio. La guía le va planteando preguntas. Sirve para repetir una prueba varias veces o preparar una práctica real. Gizmos ofrece gratis una selección rotativa de simulaciones y el resto solo deja una vista previa de 5 minutos al día sin suscripción"], "anatomy3d": ["explorar-por-materias", ["S"], 1, "Ciencias y Matemáticas", "Estudiar anatomía Explorar el cuerpo en 3D Repasar con apoyo visual Dibujar la figura humana Anatomy 3D Atlas es una aplicación con modelos anatómicos en 3D muy detallados. Se pueden girar, ampliar y separar por sistemas: esqueleto, músculos, órganos o sistema nervioso. El alumnado elige una estructura, la mira desde cualquier ángulo y ve qué tiene alrededor. Funciona bien con un encargo concreto, como localizar varias partes, dibujarlas en el cuaderno y explicarlas después a un compañero. "], "vertebrados": ["explorar-por-materias", ["P", "S"], 1, "Ciencias y Matemáticas", "Investigar especies Conocer la fauna del entorno Usar fuentes científicas Preparar trabajos Vertebrados ibéricos es una enciclopedia del CSIC con fichas de los anfibios, reptiles, aves y mamíferos de la Península, Baleares y Canarias. Cada ficha recoge su descripción, hábitat y distribución. También trata la alimentación, la reproducción, el comportamiento y la conservación. El alumnado puede elegir una especie de su zona y hacer su propia ficha. Como todas siguen el mismo esquema, se comparan bien dos especies. "], "bolsa": ["explorar-por-materias", ["S"], 1, "Ciencias y Matemáticas", "Entender cómo funciona la bolsa Competir por equipos Relacionar noticias y mercados Trabajar la educación financiera La Bolsa Virtual es un simulador de bolsa gratuito con dinero ficticio. El alumnado compra y vende acciones y puede competir en retos con un ranking privado. Ojo: la web muestra publicidad de brókeres reales. En clase conviene fijar unas fechas para el reto y pedir que cada grupo apunte por qué compra o vende. Al final no se mira solo quién ha ganado más. Se comentan las decisiones, los errores y el riesgo de invertir. La Bolsa Virtual es un simulador de bolsa gratuito para aprender a invertir"], "tinkercad": ["programacion-y-diseno-3d", ["P", "S"], 1, "Programación y diseño 3D", "Diseñar en 3D Simular circuitos Iniciarse en Arduino Preparar piezas para imprimir Tinkercad es una herramienta gratuita de Autodesk para diseñar en 3D, montar y simular circuitos electrónicos y programar con bloques. Funciona en el navegador y el docente puede crear clases para que el alumnado entre sin correo. En los circuitos se colocan y se cablean los componentes, incluidas las placas Arduino y micro:bit. Así se ve si funcionan antes de montarlos de verdad. Tinkercad es una aplicación web gratuita de Autodesk para diseño 3D, electrónica y programación"], "wokwi": ["programacion-y-diseno-3d", ["S"], 1, "Programación y diseño 3D", "Simular circuitos Programar placas como Arduino Practicar electrónica sin material Iniciarse en MicroPython Wokwi es un simulador de electrónica en línea: eliges una placa (Arduino Uno, Mega o Nano, ESP32, STM32 o Raspberry Pi Pico), le conectas componentes como LED, sensores o pantallas y la programas en el lenguaje de Arduino o en MicroPython para ver si funciona sin tener el material. Funciona en el navegador y la web está en inglés. Wokwi tiene un plan gratuito con simulaciones ilimitadas y los planes de pago añaden proyectos no listados y más funciones"], "scratch": ["programacion-y-diseno-3d", ["P", "S"], 1, "Programación y diseño 3D", "Iniciarse en la programación Crear juegos y animaciones Contar historias interactivas Trabajar con otras materias Scratch es un lenguaje de programación por bloques para crear juegos, animaciones e historias interactivas. Nació en el MIT y hoy lo mantiene la Scratch Foundation. Los bloques encajan como piezas, así que no hay errores de escritura. Además, se pueden compartir y remezclar proyectos de otras personas. El alumnado elige personajes y fondos de una biblioteca o los dibuja. Después une bloques para decidir qué hace cada uno y prueba el resultado. "], "scratchjr": ["programacion-y-diseno-3d", ["I", "P"], 1, "Programación y diseño 3D", "Iniciarse en la programación Contar historias animadas Ordenar pasos para resolver un reto Trabajar en pareja con una tablet ScratchJr es una app para que niños de 5 a 7 años programen sus propias historias y juegos uniendo bloques gráficos. Nace de Scratch y la publica la Scratch Foundation. Los personajes se mueven, saltan, bailan o cantan según los bloques que se encajan. También se pueden retocar en el editor de dibujo y añadir voces, sonidos y fotos. En clase, conviene pensar antes la historia en papel y después programarla. "], "snap": ["programacion-y-diseno-3d", ["S"], 1, "Programación y diseño 3D", "Dar el salto desde Scratch Trabajar funciones y listas Hacer proyectos con datos Profundizar en programación Snap! es un lenguaje de programación por bloques de la Universidad de Berkeley, parecido a Scratch pero con conceptos más avanzados, como funciones propias, listas y recursividad. La gran diferencia está en que el alumnado puede crear bloques nuevos y usarlos como los demás. También puede hacer listas de listas. Encaja cuando el grupo ya se maneja con Scratch y pide proyectos más complejos. "], "blockly": ["programacion-y-diseno-3d", ["P", "S"], 1, "Programación y diseño 3D", "Iniciarse en la programación Trabajar bucles y condiciones Practicar de forma autónoma Preparar una sesión corta Blockly Games es una serie de juegos libres para aprender a programar con bloques. Cada juego plantea retos, como laberintos, dibujos o música, que van introduciendo bucles, condiciones y funciones. El alumnado encaja los bloques, ejecuta el programa y ve al momento si funciona. Si falla, lo corrige y vuelve a probar. La dificultad sube poco a poco y el docente puede ayudar a quien se atasca. "], "codeorg": ["programacion-y-diseno-3d", ["I", "P", "S"], 1, "Programación y diseño 3D", "Iniciarse en la programación Participar en Hour of AI Entender la inteligencia artificial Seguir cursos por niveles Code.org ofrece cursos y actividades gratuitas de programación por niveles, con actividades de una hora y materiales para entender cómo funciona la inteligencia artificial. El docente crea una clase y sigue el progreso del alumnado. El alumnado lee el reto, prueba su solución y pasa al siguiente. El docente puede empezar con una actividad suelta o seguir un curso entero durante varias semanas. La organización que lo hace se llama ahora CodeAI y «Code.org» es su antigua marca"], "appinventor": ["programacion-y-diseno-3d", ["S"], 1, "Programación y diseño 3D", "Crear apps Resolver problemas reales Trabajar por proyectos Aprender programación MIT App Inventor permite crear aplicaciones para móviles Android e iPhone programando con bloques. Se diseña la pantalla, se programa su comportamiento y se prueba la app en el móvil al momento. Tiene dos partes, una para colocar botones, imágenes o textos y otra para encajar los bloques que dicen qué hace cada elemento. El alumnado puede empezar con una app de un solo botón y añadir funciones después. "], "thunkable": ["programacion-y-diseno-3d", ["S"], 1, "Programación y diseño 3D", "Crear apps Prototipar ideas Trabajar el emprendimiento Aprender programación Thunkable sirve para crear aplicaciones para iOS, Android y web sin escribir código. Se describe la app con palabras y la IA propone las pantallas, el diseño y su funcionamiento. Después se cambia con más indicaciones o con un editor visual. Conviene llegar con un boceto en papel para que la idea sea del alumnado. El resultado se prueba en el navegador o en el móvil. "], "cospaces": ["programacion-y-diseno-3d", ["P", "S"], 1, "Programación y diseño 3D", "Recrear espacios en 3D Crear museos virtuales Programar escenas Trabajar por proyectos Delightex Edu (antes CoSpaces Edu) permite crear mundos en 3D, realidad virtual y realidad aumentada y programar lo que ocurre en ellos con bloques. El alumnado entra con un código de la clase del docente. Construye su escena, decide qué pasa en ella y la prueba. Después la enseña y los demás la recorren. Conviene pedir antes un boceto en papel con el espacio, los textos y lo que se va a programar. "], "coppelia": ["programacion-y-diseno-3d", ["S"], 1, "Programación y diseño 3D", "Simular robots Programar en Python Trabajar robótica sin material Profundizar en Tecnología CoppeliaSim es un simulador de robótica profesional. Permite montar robots y brazos robóticos virtuales y programarlos en Python o Lua. Tiene una versión educativa y se instala en el ordenador. El alumnado monta la escena, escribe el código y ve cómo se mueve el robot. Si algo falla, lo corrige sin romper nada. Los motores de física simulan choques y agarres, para que se parezca a uno real. La licencia de CoppeliaSim Edu solo permite usarla a estudiantes y docentes de centros educativos y sin fines comerciales"], "stellarium": ["explorar-por-materias", ["P", "S"], 1, "Ciencias y Matemáticas", "Observar el cielo desde clase Reconocer constelaciones Seguir el movimiento de los planetas Preparar una observación real Stellarium es un planetario gratuito de código abierto para el ordenador. Muestra un cielo realista en 3D, como se ve a simple vista, con prismáticos o con un telescopio. También permite controlar el tiempo y simular eclipses. En clase se elige un lugar y una fecha y se mira qué se ve. El grupo puede adelantar las horas y anotar cómo cambia el cielo. Se pueden mostrar los límites y los dibujos de las constelaciones. "], "polypad": ["explorar-por-materias", ["P", "S"], 1, "Ciencias y Matemáticas", "Visualizar fracciones Explorar polígonos y mosaicos Resolver ecuaciones con balanza Experimentar con el azar Polypad es una colección de materiales manipulativos digitales de Amplify. En un mismo lienzo se mueven fracciones, polígonos, sólidos, rectas numéricas, fichas algebraicas, balanzas o dados. El alumnado arrastra las piezas, las junta y ve qué ocurre. El docente puede proyectarlo para explicar o repartir una actividad y ver el trabajo en directo. La web reúne además actividades, rompecabezas y planes de clase. "], "phyphox": ["explorar-por-materias", ["S"], 1, "Ciencias y Matemáticas", "Medir en experimentos reales Analizar datos propios Estudiar movimiento y sonido Comprobar una hipótesis phyphox convierte el móvil en un laboratorio: usa sus sensores para medir en experimentos de física. La desarrolla la universidad RWTH de Aquisgrán. Los datos se pueden exportar para analizarlos. Cada equipo elige un experimento, coloca el móvil en el montaje y pone en marcha la medición, por ejemplo la de un péndulo. Además de los experimentos que trae, el docente puede crear los suyos con un editor web. "], "makecode": ["programacion-y-diseno-3d", ["P", "S"], 1, "Programación y diseño 3D", "Iniciarse en la programación Probar programas sin la placa Pasar de bloques a código Crear proyectos con sensores MakeCode es el editor de Microsoft para programar la placa micro:bit. Se puede trabajar con bloques, JavaScript o Python y probar el programa en un simulador, aunque no se tenga la placa. Se arrastran los bloques, se prueba el programa en el simulador y, cuando funciona, se pasa a la placa. Con los mismos bloques se puede ver el código en texto. Sirve para proyectos sencillos, como un dado o un termómetro. "], "falstad": ["explorar-por-materias", ["S"], 1, "Ciencias y Matemáticas", "Simular circuitos Comprobar la ley de Ohm Comparar serie y paralelo Experimentar sin material Falstad es un simulador de circuitos eléctricos y electrónicos, libre y gratuito. Se colocan pilas, resistencias, condensadores o interruptores y el circuito funciona al momento: unos puntos en movimiento muestran por dónde circula la corriente. Se cambia un valor y se ve el efecto enseguida. La interfaz está en español, aunque la ayuda y la página principal están en inglés. "], "musescore": ["explorar-por-materias", ["S"], 1, "Música y Arte", "Componer Hacer arreglos Analizar partituras Practicar la lectura musical MuseScore es un programa libre y gratuito para escribir, editar y reproducir partituras. Se escriben las notas con el ratón o el teclado y se pueden escuchar al momento con distintos instrumentos. Sirve para escribir desde una melodía de flauta hasta un arreglo para un coro. El alumnado oye lo que ha escrito, detecta los fallos y los corrige. La partitura terminada se puede imprimir para tocarla en clase. MuseScore es un programa de código abierto y completamente gratuito, sin limitaciones"], "incredibox": ["explorar-por-materias", ["I", "P", "S"], 1, "Música y Arte", "Trabajar el ritmo Entender la textura musical Componer en grupo Motivar en clase de Música Incredibox es una aplicación para crear música arrastrando sonidos sobre unos personajes animados. Cada personaje aporta una voz, un ritmo o un efecto y la combinación forma una canción. El alumnado prueba, quita y añade capas hasta encontrar una mezcla que le guste. No hace falta saber solfeo. Al trabajar por capas, se oye qué aporta cada sonido. Después cada grupo puede presentar su mezcla. "], "musiclab": ["explorar-por-materias", ["I", "P", "S"], 1, "Música y Arte", "Componer melodías sencillas Relacionar sonido e imagen Trabajar agudos y graves Crear música sin saber solfeo Chrome Music Lab es una web de Google con experimentos para aprender música jugando. El más conocido es Song Maker: una cuadrícula en la que se pinta una melodía que luego se comparte con un enlace. Cada experimento trata una idea musical. El alumnado toca, cambia algo y escucha qué ocurre. Se puede hacer con la clase entera ante la pantalla o dejar que cada pareja pruebe y explique después lo que ha oído. "], "musictheory": ["explorar-por-materias", ["S"], 1, "Música y Arte", "Practicar el lenguaje musical Entrenar el oído Repasar de forma autónoma Reforzar contenidos musictheory.net ofrece lecciones y ejercicios gratuitos de lenguaje musical: lectura de notas, intervalos, escalas, acordes y entrenamiento auditivo. Los ejercicios se pueden configurar por nivel. Las lecciones explican cada concepto paso a paso, desde el pentagrama hasta las progresiones de acordes. Luego vienen los ejercicios: reconocer una nota, construir un intervalo o identificar lo que suena. Todo el contenido de musictheory.net es gratuito y sin anuncios y se financia con sus aplicaciones de pago"], "librecad": ["explorar-por-materias", ["S"], 1, "Música y Arte", "Dibujar vistas de piezas Hacer planos Iniciarse en el diseño asistido Trabajar el dibujo técnico LibreCAD es un programa libre y gratuito de dibujo técnico en 2D. Permite dibujar piezas, planos y vistas con precisión, como en los programas profesionales de diseño asistido. Se instala en el ordenador. El alumnado puede pasar a limpio un croquis hecho a mano, como las vistas de una pieza o el plano del aula. Cada dibujo se guarda, se corrige y se amplía sin empezar de cero. Es 2D: no hace modelos en tres dimensiones. LibreCAD es un programa de CAD en 2D libre y gratuito, con licencia GPLv2"], "learningmusic": ["explorar-por-materias", ["S"], 1, "Música y Arte", "Iniciarse en la composición Entender ritmo, escala y acorde Analizar canciones conocidas Crear una base musical Learning Music es una web de Ableton con lecciones interactivas para empezar a componer. Recorre ritmos, notas y escalas, acordes, líneas de bajo, melodías y la estructura de las canciones. Todo se practica en la propia página. Se empieza activando casillas de una cuadrícula que contienen frases musicales. Después cada uno crea sus propios patrones. Varias lecciones parten de canciones conocidas, útiles para analizarlas. "], "krita": ["explorar-por-materias", ["S"], 1, "Música y Arte", "Pintar e ilustrar en digital Aprender a trabajar por capas Crear cómics y carteles Animar fotograma a fotograma Krita es un programa profesional de pintura digital, libre y de código abierto, creado por artistas. Tiene distintos motores de pinceles, capas, asistentes de dibujo y herramientas para animar en 2D. Las capas separan el boceto, la línea y el color, así que se corrige una parte sin tocar el resto. Para los cómics trae bocadillos vectoriales. En las animaciones se puede añadir audio y el resultado se exporta como vídeo. "], "lekids": ["explorar-por-materias", ["I", "P"], 1, "Idiomas", "Escuchar canciones y cuentos Practicar vocabulario jugando Trabajar la gramática con vídeos Imprimir fichas y tarjetas LearnEnglish Kids es la web gratuita del British Council para niños de 5 a 12 años que aprenden inglés. Reúne juegos, canciones, cuentos y vídeos con actividades para hacer en pantalla o imprimir. Puedes proyectar una canción o un cuento para toda la clase y seguir con las actividades que lo acompañan. También hay chistes, trabalenguas y adivinanzas. La web está en inglés, así que los más pequeños necesitan ayuda. "], "leteens": ["explorar-por-materias", ["S"], 1, "Idiomas", "Practicar listening y reading Repasar gramática y vocabulario Preparar exámenes de inglés Trabajar cada uno a su nivel LearnEnglish Teens es la web gratuita del British Council para estudiantes de 13 a 17 años que aprenden inglés. Ordena vídeos, audios, textos y ejercicios por destrezas y por niveles. Cada alumno elige su nivel, escucha un audio o lee un texto y resuelve los ejercicios interactivos. También trabaja la escritura y la expresión oral. Además, hay apartados de gramática, vocabulario y exámenes, con consejos para prepararlos. "], "writeimprove": ["explorar-por-materias", ["S"], 1, "Idiomas", "Practicar redacciones en inglés Corregir y volver a escribir Conocer el nivel de un texto Preparar el writing de un examen Write & Improve es una herramienta gratuita de la Universidad de Cambridge para practicar la escritura en inglés. El alumno escribe un texto y recibe al momento una corrección automática con su nivel orientativo. Se elige una tarea de su nivel o se crea una propia. Lo importante viene tras la corrección: cambiar lo señalado y volver a enviarlo. En clase pueden explicar qué han mejorado entre la primera y la última versión. "], "tv5monde": ["explorar-por-materias", ["S"], 1, "Idiomas", "Trabajar la comprensión oral Saber el nivel de francés Practicar a su ritmo Preparar la clase de francés TV5MONDE es la cadena internacional en francés. Su web para aprender el idioma reúne vídeos con ejercicios de comprensión, ordenados por niveles. También tiene un test para saber por dónde empezar. El alumnado ve un fragmento de un programa o un reportaje de actualidad y hace los ejercicios en la misma web. Puede hacerse con toda la clase o cada uno con auriculares, parando y repitiendo cuando lo necesite. "], "dwdeutsch": ["explorar-por-materias", ["S"], 1, "Idiomas", "Trabajar la comprensión oral Repasar gramática y vocabulario Practicar alemán a su ritmo Preparar la clase de alemán DW Learn German es la web para aprender alemán de Deutsche Welle, la emisora internacional alemana. Reúne cursos con vídeos, audios y actividades interactivas, ordenados por niveles, además de noticias y música para aprender. Una de sus series es «Nicos Weg», que cuenta una historia por capítulos con una situación y un punto de gramática en cada uno. El alumnado ve el vídeo, hace los ejercicios y pasa al siguiente. "], "duolingo": ["explorar-por-materias", ["S"], 1, "Idiomas", "Practicar vocabulario Repasar en casa Empezar un idioma nuevo Reforzar la comprensión Duolingo es una web y una aplicación para practicar idiomas con lecciones cortas en forma de juego: traducir, escuchar, ordenar frases y repetir palabras. Cada alumno avanza por unidades y gana puntos al completarlas. Las lecciones se adaptan a cómo lo va haciendo. No sustituye a hablar y escribir con los demás: sirve para fijar palabras y estructuras que luego se usan en el aula. "], "forvo": ["explorar-por-materias", ["S"], 1, "Idiomas", "Comprobar una pronunciación Comparar acentos Preparar lecturas en voz alta Resolver dudas de pronunciación Forvo es una guía de pronunciación: se busca una palabra y se escucha dicha por hablantes nativos de ese idioma. Sirve para cualquier lengua que se estudie en el centro. El alumnado oye la palabra, la repite y se fija en cómo la dicen varias personas. Va bien para nombres propios, topónimos y palabras sueltas de un texto. Antes de escucharla, pueden decir en voz alta cómo creen que suena. "], "deepl": ["explorar-por-materias", ["S"], 1, "Idiomas", "Comparar traducciones Revisar un texto propio Entender textos en otro idioma Ver los límites del traductor DeepL es un traductor automático basado en IA. Se pega o se escribe un texto, se elige el idioma y devuelve la traducción, que después se puede corregir. En clase funciona bien si cada alumno traduce antes por su cuenta y luego mira las dos versiones. Se buscan las diferencias, se decide cuál es mejor y se explica por qué. También se puede probar con una expresión hecha o una frase con doble sentido. "], "dicta": ["explorar-por-materias", ["P", "S"], 1, "Idiomas", "Practicar la ortografía Entrenar el oído en otro idioma Hacer dictados a su ritmo Preparar dictados propios Dicta2.0 es una web para hacer dictados: lee una oración en voz alta, el alumno la escribe y al pulsar «Corregir» ve la oración correcta. Funciona en español, inglés, francés, alemán, italiano y portugués. Hay dos maneras de usarla. En una, la web propone oraciones al azar en el idioma elegido. En la otra, el alumnado introduce un código y hace el dictado que ha preparado su docente. "], "gtranslate": ["explorar-por-materias", ["S"], 1, "Idiomas", "Traducir textos y documentos Traducir el texto de una imagen Comparar traducciones Entender una web en otro idioma El Traductor de Google traduce al momento entre idiomas. Además de texto escrito o dictado, admite imágenes, documentos y sitios web enteros. En clase, el alumnado puede traducir primero por su cuenta, mirar después la propuesta y buscar los fallos. Así se trabaja el sentido de la frase y no solo la palabra. Conviene revisar siempre la traducción con el texto original. "], "apertium": ["explorar-por-materias", ["S"], 1, "Idiomas", "Traducir entre lenguas cercanas Comparar traductores Detectar errores de traducción Conocer el software libre Apertium es una plataforma libre de traducción automática. Traduce textos, documentos y páginas web sin crear cuenta. Entre sus idiomas están el catalán y el gallego. Se elige el idioma de partida y el de llegada y se escribe el texto. El alumnado puede subrayar lo que no suena natural y escribir una versión mejor, explicando cada cambio. Así el traductor sirve para hablar de gramática y vocabulario. "], "kinovea": ["explorar-por-materias", ["S"], 1, "Educación Física", "Analizar un gesto deportivo Comparar dos técnicas Medir ángulos y tiempos Relacionar deporte y física Kinovea es un programa libre para analizar el movimiento deportivo en vídeo. Permite ralentizar, comparar dos vídeos, añadir anotaciones y medir ángulos, distancias y tiempos. Se abre el vídeo de un deportista y se avanza despacio hasta el momento que interesa. Sobre la imagen se dibujan líneas, flechas o ángulos. También se puede seguir la trayectoria de un punto para explicar después el gesto con datos. "], "schoolai": ["inteligencia-artificial", ["S"], 1, "IA para el alumnado", "Repasar con un tutor de IA Hacer tickets de salida Detectar dificultades Practicar con supervisión SchoolAI sirve para que el docente cree espacios de conversación con un tutor de inteligencia artificial que sigue sus reglas y límites. El alumnado entra con un enlace y el docente ve en directo las conversaciones y quién necesita ayuda. Tú decides el tema y lo que debe hacer la IA. Cada alumno avanza con sus propias preguntas. Al terminar, puedes usar lo que han escrito para decidir qué hay que volver a explicar. "], "snorkl": ["inteligencia-artificial", ["S"], 1, "IA para el alumnado", "Explicar razonamientos Practicar la expresión oral Detectar ideas previas Recibir retroalimentación Snorkl pide al alumnado que explique su razonamiento en voz alta y con dibujos sobre una pizarra. La inteligencia artificial analiza la explicación y le devuelve comentarios para mejorarla. El docente propone la actividad y cada alumno graba su respuesta mientras dibuja o escribe. Con los comentarios puede volver a intentarlo. Tú ves cómo piensa cada uno y no solo si ha acertado. "], "immersive": ["explorar-por-materias", ["P", "S"], 1, "Lectura y accesibilidad", "Apoyar la lectura Atender a la diversidad Traducir textos Mejorar la comprensión lectora El Lector inmersivo es una herramienta gratuita de Microsoft integrada en Edge, Word, OneNote y Teams. Lee el texto en voz alta, lo traduce, lo separa en sílabas, marca las clases de palabras y permite cambiar el tamaño y el espaciado de las letras. El alumno elige cómo quiere leer y sigue el texto a su velocidad. El docente no prepara otra versión: todos leen lo mismo. Microsoft presenta el Lector inmersivo como una herramienta gratuita integrada en Word, OneNote, Teams, Edge y otras aplicaciones de Microsoft 365"], "languagetool": ["explorar-por-materias", ["S"], 1, "Lectura y accesibilidad", "Corregir ortografía Revisar gramática Mejorar el estilo Escribir en otro idioma LanguageTool es un corrector de ortografía, gramática y estilo que funciona en varios idiomas, entre ellos el español y el inglés. El alumno pega su texto en el editor y recibe sugerencias de corrección. Lo útil en clase es que no las acepte todas sin leer: puede anotar sus fallos, buscar la regla y decidir si cambia la frase. También sugiere otras formas de escribir una oración. El plan gratuito de LanguageTool corrige hasta 2.000 caracteres por texto"], "readwrite": ["explorar-por-materias", ["S"], 1, "Lectura y accesibilidad", "Apoyar la lectura Atender a la diversidad Escribir con dictado Reforzar el vocabulario Read&Write, de Everway (antes Texthelp), es una barra de herramientas de apoyo a la lectura y la escritura. Incluye lectura en voz alta, dictado por voz, predicción de palabras y un diccionario con imágenes. Se instala como extensión del navegador. El alumnado abre la barra sobre el texto que lee o escribe y elige la ayuda que necesita. Puede escuchar un enunciado o dictar una respuesta y hacer la misma tarea que el resto. "], "learningml": ["inteligencia-artificial", ["P", "S"], 1, "IA para el alumnado", "Entender cómo aprende una IA Entrenar y probar un modelo Hablar de sesgos y errores Programar con IA en Scratch LearningML es una plataforma educativa para entender cómo aprende una inteligencia artificial. Se reúnen ejemplos, se entrena un modelo y se comprueba si acierta. Después, el modelo se puede usar en un proyecto de Scratch. En clase, cada pareja elige qué quiere clasificar, por ejemplo textos alegres y tristes. Después reúne ejemplos de cada clase. Si el modelo falla, toca pensar por qué y añadir o cambiar ejemplos. "], "gemini": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Preparar actividades Adaptar textos Generar ideas Diseñar situaciones de aprendizaje Gemini es el asistente de inteligencia artificial de Google. Con la cuenta de Google Workspace for Education del centro está incluido y, según Google, las conversaciones no se usan para entrenar sus modelos. Sirve para preparar explicaciones, actividades y materiales adaptados. El docente concreta curso, tema y nivel. Si algo no encaja, pide cambios en el mismo chat. Siempre hay que revisar el resultado. "], "notebooklm": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Resumir documentos Preparar guías de estudio Crear preguntas de repaso Revisar la programación NotebookLM es una herramienta de Google que responde solo a partir de los documentos que le subes: apuntes, artículos, la programación o un vídeo. Cada respuesta cita el fragmento exacto de donde sale, lo que la hace más fiable que un chat general. También genera resúmenes, guías de estudio y audios. Google la presenta ahora como Gemini Notebook"], "copilot": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Adaptar materiales Resumir documentos Preparar preguntas Generar ideas Microsoft Copilot Chat es el asistente de inteligencia artificial de Microsoft. En centros con Microsoft 365 Educación está disponible sin coste adicional y funciona también en Outlook y Teams. Usarlo dentro de Word o PowerPoint depende de la licencia. El docente escribe lo que necesita o sube un archivo y le pide un cambio, como un texto más sencillo. La respuesta es un borrador que conviene comprobar antes de llevarlo a clase. Copilot Chat está incluido sin coste adicional con las licencias Microsoft 365 A1, A3 y A5 al entrar con la cuenta del centro"], "chatgpt": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Preparar explicaciones Adaptar textos Generar ejemplos Diseñar juegos de rol ChatGPT, de OpenAI, es el asistente de inteligencia artificial más conocido. Además de conversar, busca en la web, trabaja con archivos que subes y crea imágenes. El docente escribe lo que necesita, con el curso y la materia, lee la respuesta y va pidiendo cambios. Puede equivocarse o inventar datos, así que hay que revisar todo antes de llevarlo a clase. Los asistentes personalizados (GPT) se retiran el 11 de diciembre de 2026 y OpenAI los sustituye por plugins"], "claude": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Crear recursos interactivos Revisar documentos largos Preparar actividades y rúbricas Generar ideas Claude, de Anthropic, es un asistente de inteligencia artificial que trabaja bien con documentos largos. Puede crear pequeñas herramientas web interactivas, como mapas, líneas del tiempo o simuladores, que se usan directamente en el navegador. El docente explica qué quiere y para qué curso. El recurso aparece junto a la conversación, se prueba y se van pidiendo cambios. Conviene comprobar los datos antes de usarlo. "], "edugems": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Planificar unidades Crear juegos de repaso Adaptar actividades Aprender a escribir buenos prompts EduGems reúne más de 160 prompts para Gemini pensados para docentes, de Eric Curts, autor del blog Control Alt Achieve. Están ordenados por tareas: planificar, crear materiales y juegos, atender a la diversidad, evaluar, lectura y escritura, ciencias o tareas administrativas. Cada uno es una plantilla que se abre en Gemini como un Gem listo para usar o se copia como texto. La web y los prompts están en inglés, aunque puedes pedir a Gemini que responda en español. Eric Curts la ha rebautizado como EduPrompts, con nueva dirección en eduprompts.ai"], "magicschool": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Crear rúbricas Generar bancos de preguntas Adaptar textos Redactar comunicaciones MagicSchool reúne decenas de generadores de inteligencia artificial pensados para docentes: rúbricas, bancos de preguntas, adaptaciones de textos o comunicaciones a familias. Está muy orientado al sistema educativo de Estados Unidos, así que conviene revisar los resultados. Eliges un generador, rellenas unos datos (por ejemplo, el tema) y recibes un borrador. También los hay de fichas, presentaciones y planes de clase. "], "diffit": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Adaptar lecturas Atender a la diversidad Crear fichas de vocabulario Preparar preguntas de comprensión Diffit convierte un tema, un texto o un enlace en una lectura adaptada al nivel que elijas, con vocabulario y preguntas de comprensión. Es muy útil para tener el mismo contenido a distintos niveles de lectura. El docente escribe qué necesita o parte de un material suyo, elige el nivel y el idioma y revisa el resultado antes de usarlo. Todo se puede editar. El alumnado recibe la lectura y las actividades ya preparadas. "], "brisk": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Crear actividades desde una web Adaptar textos Comentar trabajos Ahorrar tiempo Brisk Teaching es una extensión de Chrome que añade inteligencia artificial a Google Docs, Slides y a cualquier página web. Permite crear actividades a partir de un artículo, cambiar el nivel de lectura de un texto o dar comentarios sobre trabajos. El docente abre el documento o la web, elige qué quiere hacer y recibe un borrador que hay que revisar. No hace falta salir del navegador. "], "chatpdf": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Resumir documentos Preparar preguntas Localizar información Revisar textos largos ChatPDF permite subir un documento PDF y hacerle preguntas sobre su contenido. La herramienta responde a partir del documento, lo que ayuda a localizar información o a preparar preguntas sobre un texto largo. Cada respuesta lleva citas que remiten al documento, así que se puede comprobar de dónde sale. El docente puede subir un artículo y pedir sus ideas principales. No sustituye a la lectura y hay que revisar lo que dice. "], "lexica": ["inteligencia-artificial", ["I", "P", "S"], 1, "IA para preparar clase", "Ilustrar materiales Explorar estilos artísticos Crear imágenes para debatir Detectar anacronismos Lexica es un buscador de imágenes creadas con inteligencia artificial y un generador de imágenes propio. Permite encontrar o crear ilustraciones en muchos estilos artísticos a partir de una descripción. Para usarlo, el docente busca una escena o la describe y compara los resultados. Luego puede proyectar algunas imágenes y pedir al alumnado que diga qué ve, qué estilo reconoce o qué detalles no encajan con la época. "], "exelearning": ["crear-y-presentar", ["I", "P", "S"], 1, "Materiales del docente", "Crear unidades didácticas Hacer actividades autocorregibles Publicar recursos en Moodle Compartir materiales abiertos eXeLearning es un programa libre y gratuito para crear recursos educativos interactivos: unidades completas con textos, imágenes, vídeos y actividades autocorregibles. El resultado se publica como web o se sube a Moodle. El docente organiza el contenido en páginas, elige un estilo y va añadiendo bloques de texto, imagen o juego. El alumnado lo recorre a su ritmo como una pequeña web. eXeLearning es una herramienta libre, gratuita y de código abierto"], "gamma": ["crear-y-presentar", ["I", "P", "S"], 1, "Materiales del docente", "Hacer presentaciones Convertir apuntes en diapositivas Crear webs sencillas Ahorrar tiempo Gamma crea presentaciones, documentos y páginas web a partir de una idea o un texto con ayuda de la inteligencia artificial. Genera un primer borrador con diseño que luego se edita a mano. Se escribe el tema o se pega el texto y la aplicación propone las páginas. Después toca revisar los datos, quitar lo que sobra y adaptarlo al grupo. También se puede partir de un PowerPoint o un PDF que ya tengas. "], "fliki": ["crear-y-presentar", ["I", "P", "S"], 1, "Materiales del docente", "Crear vídeos introductorios Preparar cápsulas para aula invertida Narrar relatos Ahorrar tiempo Fliki crea vídeos con voz a partir de un guion o una idea. La inteligencia artificial elige imágenes, añade una voz en off y monta el vídeo, que luego se puede ajustar. El docente escribe el texto o pega el enlace de un artículo y recibe un guion dividido en escenas. Puede corregir cada frase, cambiar las imágenes por otras propias y reordenar las escenas. Conviene revisar el vídeo entero antes de ponerlo en clase. "], "elevenlabs": ["crear-y-presentar", ["I", "P", "S"], 1, "Materiales del docente", "Narrar textos y relatos Crear diálogos entre personajes Poner voz a vídeos y presentaciones Adaptar materiales en audio ElevenLabs convierte un texto escrito en audio con voces de inteligencia artificial muy naturales, en español y en muchos otros idiomas. Permite elegir la voz, el tono y el ritmo, hacer diálogos entre varias voces y doblar un audio o un vídeo a otro idioma. El docente pega el texto, escoge una voz, escucha el resultado y lo ajusta. Al final descarga un archivo de audio que se puede poner en clase. "], "loom": ["crear-y-presentar", ["I", "P", "S"], 1, "Materiales del docente", "Grabar explicaciones Preparar aula invertida Hacer tutoriales Dar comentarios en vídeo Loom graba a la vez la pantalla del ordenador y la cámara y comparte el vídeo con un enlace al instante. Es muy práctico para explicar algo una vez y que el alumnado lo vea cuando lo necesite. Antes de enviarlo, puedes recortar el vídeo y añadir dibujos para señalar algo. Quien lo ve puede dejar comentarios. Sirve para mostrar los pasos de una tarea o para comentar un trabajo mientras lo recorres. Loom ya no ofrece su plan gratuito para docentes: ahora hay un 75 % de descuento en las licencias de aula"], "picsart": ["crear-y-presentar", ["I", "P", "S"], 1, "Materiales del docente", "Editar imágenes Crear portadas Preparar materiales visuales Diseñar contenido para el aula PicsArt es un editor de imágenes para móvil y web. Permite recortar, quitar fondos, añadir textos, pegatinas y efectos con plantillas listas para usar. Con él preparas la portada de una unidad, un cartel o una imagen para la cuenta del aula. Partes de una foto propia o de una plantilla y cambias lo que necesites. Ahora da mucho espacio a la creación de imágenes y vídeos con inteligencia artificial. "], "arasaac": ["crear-y-presentar", ["I", "P", "S"], 1, "Materiales del docente", "Crear horarios visuales Preparar tableros de comunicación Hacer bingos y dominós Adaptar materiales con pictogramas ARASAAC es el centro aragonés de comunicación aumentativa y alternativa, del Gobierno de Aragón. Ofrece un buscador de pictogramas y materiales. Con su herramienta ARActivities se preparan tableros, calendarios, horarios, bingos, dominós, tiras de intrusos y dados recortables. El docente busca una palabra, elige el pictograma que mejor la representa y lo lleva a su material. Vale para un alumno o para toda la clase. "], "classroom": ["aulas-virtuales", ["I", "P", "S"], 1, "Aulas virtuales", "Organizar tareas Compartir materiales Corregir con comentarios Comunicarse con el grupo Google Classroom es el aula virtual de Google. El docente crea una clase, publica materiales y tareas, las corrige con comentarios y pone calificaciones. El alumnado entrega desde cualquier dispositivo con la cuenta del centro. Las novedades salen en el tablón y las tareas pueden llevar archivos de Drive, vídeos o formularios. Cada alumno ve lo que tiene pendiente y lee los comentarios de sus trabajos en el mismo sitio. "], "teams": ["aulas-virtuales", ["I", "P", "S"], 1, "Aulas virtuales", "Organizar tareas Compartir materiales Comunicarse con el grupo Recoger respuestas en vídeo Microsoft Teams Educación es el aula virtual de Microsoft. Cada grupo tiene su equipo con conversaciones, tareas, calificaciones y un bloc de notas de clase. También permite respuestas en vídeo como las que ofrecía Flip. El docente publica los materiales y pone las tareas. El alumnado entrega allí su trabajo y pregunta sus dudas. Los grupos pueden trabajar a la vez en un mismo archivo de Word, Excel o PowerPoint. "], "moodle": ["aulas-virtuales", ["I", "P", "S"], 1, "Aulas virtuales", "Crear cursos en línea Hacer cuestionarios Diseñar itinerarios Seguir la actividad del alumnado Moodle es una plataforma libre de aulas virtuales que usan muchas administraciones educativas. En Andalucía se llama Moodle Centros. Permite crear cursos con materiales, tareas, foros, cuestionarios e itinerarios. También permite seguir la actividad del alumnado. El docente ordena el curso por temas y reúne en cada uno los apuntes y las actividades. Las preguntas de los cuestionarios se guardan en un banco y se reutilizan. "], "additio": ["gestion-del-aula", ["I", "P", "S"], 1, "Gestión del aula", "Evaluar por criterios Registrar asistencia Planificar sesiones Usar rúbricas Additio es un cuaderno del profesor digital. Reúne en un mismo sitio las notas, la asistencia, las observaciones, las rúbricas y la planificación de las sesiones, con evaluación por criterios y competencias. El docente crea sus grupos, elige cómo quiere calificar y anota en el cuaderno a medida que avanza el curso. Cada dato queda junto al nombre del alumno, así que es más fácil preparar una tutoría o justificar una nota. Los planes para docentes son de pago, desde 13,99 € al año"], "idoceo": ["gestion-del-aula", ["I", "P", "S"], 1, "Gestión del aula", "Llevar el cuaderno de evaluación Planificar el curso Guardar evidencias Registrar observaciones iDoceo es un cuaderno del profesor muy completo para iPad, iPhone y Mac. Incluye cuaderno de evaluación, planificador, diario de clase y evidencias por alumno. Los datos se guardan en el propio dispositivo. El cuaderno admite notas, iconos, textos y rúbricas. Calcula medias simples o ponderadas y también con fórmulas propias. La lista del grupo se puede importar desde una hoja de cálculo. "], "classdojo": ["gestion-del-aula", ["I", "P", "S"], 1, "Gestión del aula", "Gamificar las normas Reconocer conductas positivas Comunicarse con las familias Crear buen clima de aula ClassDojo es una herramienta de gestión del aula y comunicación con familias. Cada alumno tiene un avatar y puede recibir puntos por actitudes positivas. Las familias reciben mensajes y fotos de la clase. El docente decide qué actitudes se valoran y da los puntos durante la clase. También hay portfolios para mostrar trabajos. Los puntos funcionan mejor si se explican antes y no se usan para señalar a nadie. "], "classroomscreen": ["gestion-del-aula", ["I", "P", "S"], 1, "Gestión del aula", "Marcar tiempos Controlar el ruido Elegir turnos al azar Organizar el trabajo cooperativo Classroomscreen es una pantalla para proyectar en clase con herramientas para gestionar la sesión: temporizador, semáforo, medidor de ruido, selector al azar, instrucciones de trabajo y mucho más. Cada herramienta es una pieza que se añade a la pantalla. El docente la prepara al empezar y la deja a la vista, así el alumnado sabe qué toca hacer y cuánto tiempo queda. También puede formar grupos o llevar un marcador. "], "fastboard": ["gestion-del-aula", ["I", "P", "S"], 1, "Gestión del aula", "Explicar con dibujos y esquemas Compartir la pizarra Dibujar a la vez en grupo Hacer participar al alumnado Fastboard es una pizarra en línea para dibujar y escribir a la vez con otras personas. Creas una pizarra, compartes el enlace y el alumnado se une desde su dispositivo, sin registrarse. En clase se proyecta la pizarra y cada grupo aporta una parte del dibujo o del esquema. Todos ven los cambios en el momento. Puede servir para explicar algo rápido o para una lluvia de ideas dibujada. "], "koalendar": ["gestion-del-aula", ["I", "P", "S"], 1, "Gestión del aula", "Organizar tutorías Citar a las familias Reservar espacios y material Evitar correos de ida y vuelta Koalendar es una agenda en línea para que otras personas reserven cita contigo. Marcas los huecos libres, compartes tu página de reservas y las familias, el alumnado o los compañeros eligen hora en pocos clics. Se sincroniza con Google Calendar, Outlook e iCloud y cada reserva puede incluir un enlace de videollamada. Tiene un plan gratuito sin límite de tiempo. Koalendar mantiene un plan gratuito sin límite de tiempo, con reservas ilimitadas y sincronización de hasta 2 calendarios"], "corubrics": ["evaluacion-y-seguimiento", ["I", "P", "S"], 1, "Evaluar y motivar", "Evaluar con rúbricas Hacer coevaluación Hacer autoevaluación Enviar resultados CoRubrics es un complemento gratuito de Hojas de cálculo de Google para evaluar con rúbricas. Sirve para la evaluación del docente, la autoevaluación y la coevaluación. Después envía los resultados a cada alumno por correo. El docente prepara la rúbrica y la lista de alumnos. El complemento crea un formulario y, cuando está contestado, calcula las medias. Cada alumno recibe solo su resultado. CoRubrics es un complemento gratuito de Hojas de cálculo de Google. Ahora tiene también una versión web con opciones premium"], "doctoform": ["evaluacion-y-seguimiento", ["I", "P", "S"], 1, "Evaluar y motivar", "Pasar exámenes a Forms Crear cuestionarios autocorregibles Incluir fórmulas e imágenes Ahorrar tiempo Doc to Form Quiz Maker es un complemento gratuito de Google Docs. Escribes las preguntas en un documento y lo convierte en un cuestionario de Google Forms que se corrige solo. Admite opción múltiple, casillas, respuesta corta, imágenes y fórmulas, con los puntos y una explicación para cada pregunta. Las marcas que reconoce, como «Answer:» o «Explanation:», van en inglés. Se instala desde el Marketplace de Google Workspace y en muchos centros tiene que permitirlo el administrador. Doc to Form Quiz Maker es un complemento gratuito de Google Docs"], "gforms": ["evaluacion-y-seguimiento", ["I", "P", "S"], 1, "Evaluar y motivar", "Hacer cuestionarios Evaluar ideas previas Hacer encuestas Autoevaluar y coevaluar Google Forms sirve para crear cuestionarios, exámenes que se corrigen solos y encuestas. Las respuestas se recogen ordenadas y se pueden pasar a una hoja de cálculo. Admite varios tipos de pregunta, imágenes y vídeos. Según lo que conteste cada persona, se le muestran unas preguntas u otras. El docente comparte el enlace y ve las respuestas en gráficos a medida que llegan. Así detecta qué ha fallado casi todo el grupo. "], "msforms": ["evaluacion-y-seguimiento", ["I", "P", "S"], 1, "Evaluar y motivar", "Hacer cuestionarios Repasar con retroalimentación Hacer encuestas Recoger datos de un proyecto Microsoft Forms permite crear cuestionarios y encuestas que se corrigen solos. Está integrado con Teams, así que se pueden asignar como tarea y recoger las notas automáticamente. El docente escribe las preguntas, marca las respuestas correctas y comparte el cuestionario con un enlace. El alumnado contesta y los resultados se ven enseguida. Las respuestas abiertas conviene revisarlas a mano. "], "jotform": ["evaluacion-y-seguimiento", ["I", "P", "S"], 1, "Evaluar y motivar", "Crear formularios Hacer encuestas Gestionar inscripciones Evaluar con rúbricas Jotform es un creador de formularios con muchos tipos de campo y plantillas. Sirve para cuestionarios, inscripciones, encuestas o rúbricas en formato formulario. El formulario se monta arrastrando los campos. Con condiciones, algunas preguntas solo aparecen según lo contestado antes. Se comparte con un enlace o un código QR. Las respuestas se guardan juntas y cada una se puede pasar a PDF. "], "learningpaths": ["evaluacion-y-seguimiento", ["I", "P", "S"], 1, "Evaluar y motivar", "Crear itinerarios Ordenar recursos paso a paso Comprobar la comprensión con preguntas Trabajar de forma autónoma Learning Paths es una función de Symbaloo que convierte un webmix en un itinerario de aprendizaje. Ya no es una web aparte, sino parte de Symbaloo. Añades los recursos que el alumnado debe leer, ver, escuchar o jugar, les pones actividades de opción múltiple o de respuesta abierta y los colocas en el orden en que hay que recorrerlos. El progreso del alumnado se guarda solo en su ordenador y en la Biblioteca de Symbaloo hay itinerarios de otros docentes para usarlos o adaptarlos. "], "badge": ["evaluacion-y-seguimiento", ["I", "P", "S"], 1, "Evaluar y motivar", "Reconocer logros Gamificar una unidad Evaluar competencias Motivar al alumnado Open Badge Designer es una herramienta gratuita para diseñar insignias digitales. Las insignias sirven para reconocer logros, competencias o actitudes y dar visibilidad al progreso del alumnado. Se parte de una forma y se añaden elementos, como una cinta o un icono. El resultado es una imagen que se puede imprimir o poner en el aula virtual. Conviene explicar antes a la clase cómo se gana cada una. Open Badge Designer es gratuito y permite descargar las insignias en SVG o PNG sin crear una cuenta"], "symbaloo": ["colaborar-y-organizar", ["I", "P", "S"], 1, "Organizar recursos", "Organizar recursos Crear un escritorio para la clase Compartir enlaces Montar un entorno personal de aprendizaje Symbaloo organiza tus enlaces favoritos en escritorios visuales con forma de mosaico. Cada recurso es un icono y se pueden crear escritorios por unidades o materias y compartirlos con el alumnado. Al pulsar un icono se abre la web enlazada. En lugar de repartir direcciones sueltas, das una sola y el grupo encuentra allí lo que necesita. También puedes ordenar ahí las webs de una unidad y reutilizar el escritorio el curso siguiente. "], "pearltrees": ["colaborar-y-organizar", ["I", "P", "S"], 1, "Organizar recursos", "Organizar recursos Compartir colecciones Preparar unidades Trabajar en equipo docente Pearltrees sirve para guardar y organizar enlaces, documentos, imágenes y notas en colecciones con forma de árbol. Las colecciones se pueden compartir con el alumnado o con el departamento. Puedes hacer una para cada curso y ordenar dentro los materiales de cada unidad. Sirve como banco de recursos: guardas lo que encuentras y lo recuperas al preparar la clase. "], "feedly": ["colaborar-y-organizar", ["I", "P", "S"], 1, "Organizar recursos", "Estar al día de tu materia Seguir blogs educativos Encontrar noticias para clase Organizar lecturas Feedly reúne en un solo sitio las novedades de las webs, blogs y revistas que sigues, sin tener que visitarlas una a una. Se añaden las fuentes que interesan y al entrar se ven los últimos artículos de todas ellas. También se puede buscar una palabra dentro de tus fuentes. La diferencia con las redes sociales es que eliges qué lees y de quién. Sirve para reunir artículos que luego se comentan en clase. "], "wakelet": ["colaborar-y-organizar", ["I", "P", "S"], 1, "Organizar recursos", "Curar contenidos Reunir fuentes de una investigación Compartir recursos Crear colecciones entre docentes Wakelet sirve para crear colecciones de enlaces, vídeos, documentos e imágenes para organizar y compartir contenido. Las colecciones pueden ser colaborativas, por ejemplo entre docentes de un departamento. Cada una se comparte con un enlace o se queda privada. Puedes pedir que cada fuente lleve una nota que explique por qué se ha elegido. El plan gratuito es para uso individual: usarlo con alumnado de un centro cuenta como uso comercial y pide el plan Education Enterprise"], "ilovepdf": ["colaborar-y-organizar", ["I", "P", "S"], 1, "Organizar recursos", "Unir documentos Convertir formatos Comprimir archivos Preparar materiales iLovePDF es un conjunto de herramientas en línea para trabajar con PDF: unir, dividir, comprimir, convertir a Word u otros formatos, girar o numerar páginas. Se elige la herramienta, se sube el archivo y se descarga el resultado. Va bien para sacar unas páginas de un dossier o juntar las fichas de un tema. También puede tomar archivos de Google Drive o Dropbox y guardarlos allí al terminar. "], "procomun": ["bancos-de-recursos", ["I", "P", "S"], 1, "Situaciones de aprendizaje", "Buscar recursos abiertos Reutilizar materiales Inspirarse para preparar clase Compartir recursos propios Procomún es el repositorio de recursos educativos abiertos del Ministerio de Educación y las comunidades autónomas. Reúne materiales de todas las etapas y materias que se pueden usar y adaptar libremente. El buscador filtra por área de conocimiento y por etapa educativa. También separa los recursos de aprendizaje, los artículos y los itinerarios. Sirve para encontrar una secuencia hecha por otro docente y llevarla a clase. "], "readua": ["bancos-de-recursos", ["I", "P", "S"], 1, "Situaciones de aprendizaje", "Usar situaciones de aprendizaje Atender a la diversidad Inspirarse para programar Adaptar materiales El banco de Recursos Educativos Abiertos de la Junta de Andalucía ofrece situaciones de aprendizaje completas, con guía docente y enfoque de Diseño Universal para el Aprendizaje (DUA). Cada una gira en torno a un reto y termina en un producto final que elabora el alumnado. El material del alumnado y la guía del docente van por separado. Puedes usar la situación entera o solo las actividades que encajen con tu grupo. "], "edia": ["bancos-de-recursos", ["I", "P", "S"], 1, "Situaciones de aprendizaje", "Usar situaciones de aprendizaje Descargar plantillas y rúbricas Inspirarse para programar Adaptar materiales El Proyecto EDIA, del CEDEC (INTEF), ofrece situaciones de aprendizaje abiertas con plantillas, guías y rúbricas, desde Infantil hasta Formación Profesional. Cada situación reparte el trabajo en tareas para el aula. Incluye una guía didáctica con la referencia curricular y el número de sesiones. El docente la busca por materia y etapa. Puede usarla entera o quedarse con una tarea. "], "bnescolar": ["bancos-de-recursos", ["I", "P", "S"], 1, "Situaciones de aprendizaje", "Trabajar con fuentes históricas Buscar secuencias didácticas Encontrar documentos por materias Inspirar un proyecto de aula BNEscolar es la propuesta de la Biblioteca Nacional de España para llevar su patrimonio al aula. Ofrece secuencias didácticas, talleres, desafíos y vídeos hechos con sus colecciones, además de un buscador de documentos digitalizados por materias. Los desafíos plantean enigmas que se resuelven con actividades y los talleres traen videotutoriales para aprender una técnica. El docente puede usar una propuesta entera o adaptarla. "], "pixabay": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Ilustrar materiales Buscar vídeos y música Preparar presentaciones Enseñar a usar imágenes libres Pixabay es un banco de imágenes, ilustraciones, vídeos y música que se pueden usar gratis, también en materiales educativos, sin necesidad de citar al autor. Reúne en el mismo sitio material gráfico y sonoro. Para un vídeo del alumnado se pueden sacar de ahí las imágenes y la música de fondo. Cada grupo busca, elige y explica por qué ese recurso encaja con su trabajo. Pixabay permite usar su contenido gratis sin tener que citar al autor"], "magnific": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Ilustrar materiales Buscar vectores e iconos Diseñar presentaciones Crear imágenes con IA Magnific es el nuevo nombre de Freepik desde 2026. Ahora se centra en la creación con inteligencia artificial, pero mantiene su biblioteca de ilustraciones, vectores, iconos e imágenes, con una parte gratuita que pide citar al autor. Sirve para buscar un dibujo o un icono para una presentación, una ficha o un cartel. Antes de descargar, comprueba si es gratuito y qué licencia tiene. El contenido gratuito de Magnific exige citar la fuente, pero con una suscripción de pago no hace falta"], "unsplash": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Ilustrar materiales Preparar presentaciones Crear portadas Enseñar a usar imágenes libres Unsplash es un banco de fotografías de alta calidad que se pueden usar gratis, también en materiales educativos, sin pedir permiso. El alumnado puede usarlas en un cartel, una presentación o una web sin copiar imágenes de cualquier sitio. Son más útiles para una portada o un fondo que para documentar un hecho histórico o una obra concreta. Un buen hábito es nombrar al fotógrafo igualmente. Unsplash permite usar sus imágenes gratis sin pedir permiso ni citar al fotógrafo"], "pexels": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Ilustrar materiales Buscar vídeos para montajes Preparar presentaciones Enseñar a usar imágenes libres Pexels ofrece fotos y vídeos gratuitos de buena calidad, muy útiles para presentaciones y montajes de vídeo del alumnado. Se busca por palabras y cada foto o vídeo se descarga directamente. El alumnado puede usarlos para ilustrar una exposición, montar un vídeo o elegir una imagen como punto de partida para escribir. Elegir bien una imagen y justificarlo ya es un ejercicio. Todas las fotos y vídeos de Pexels son de uso gratuito y no exigen citar al autor"], "wikicommons": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Buscar imágenes y mapas Usar documentos históricos Enseñar a citar Ilustrar materiales Wikimedia Commons es el banco de archivos de Wikipedia: millones de imágenes, mapas, audios y documentos históricos con licencia libre. Cada archivo indica su autor y su licencia, por lo que sirve para aprender a citar. Los archivos se agrupan en categorías. El alumnado busca una imagen, abre su página, comprueba de dónde sale y la pone en su trabajo con el autor y la licencia. "], "openverse": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Buscar imágenes libres Buscar sonidos Enseñar a citar Ilustrar materiales Openverse es un buscador de imágenes y sonidos con licencias abiertas, impulsado por WordPress. Muestra la licencia de cada resultado y facilita la forma de citarlo. Escribes una palabra y eliges si buscas imágenes o audio. En clase, cada alumno puede buscar una foto para su trabajo, leer qué deja hacer la licencia y poner la cita al pie. Así se aprende que no todo lo que hay en internet se puede copiar. "], "europeana": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Buscar fuentes históricas Analizar obras de arte Investigar Ilustrar materiales Europeana es la gran biblioteca digital del patrimonio europeo. Reúne cuadros, fotografías, mapas, libros y documentos digitalizados por museos, archivos y bibliotecas de toda Europa. Se puede buscar por palabras o entrar por temas, como arte, fotografía, música o periódicos. También publica historias que explican obras y épocas. El alumnado compara varias fuentes sobre un mismo hecho y mira quién hizo cada una y cuándo. "], "metmuseum": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Analizar obras de arte Ilustrar materiales Investigar Preparar presentaciones El Metropolitan Museum de Nueva York ofrece en acceso abierto imágenes en alta resolución de una gran parte de su colección. Las obras de dominio público se pueden descargar y usar libremente. Puedes proyectar una obra y ampliarla para observar sus detalles con la clase. Cada pieza lleva sus datos básicos. El alumnado puede comparar varias obras, hacer un comentario o reinterpretar una pieza en un trabajo propio. "], "flaticon": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Ilustrar materiales Diseñar infografías Crear presentaciones Señalizar el aula Flaticon es un banco de iconos y pegatinas, también animados, en muchos estilos. Una parte es gratuita si se cita al autor. Se busca una palabra, se comparan estilos y se descarga el icono que encaja. En una ficha ayudan a reconocer cada tarea: un icono para leer, otro para escribir y otro para el trabajo en grupo. El alumnado puede usarlos en sus pósteres y citar de dónde salen. Con la cuenta gratuita de Flaticon hay que citar al autor y enlazar a Flaticon. Solo la suscripción Premium evita la atribución"], "sketchfab": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Explorar modelos 3D Analizar piezas de museo Usar realidad virtual Ilustrar explicaciones Sketchfab es una plataforma de modelos 3D: monumentos, piezas de museo, fósiles, objetos o personajes. Se pueden girar y ampliar en el navegador y ver en realidad virtual. En clase puedes proyectar un modelo y girarlo mientras lo explicas. El grupo ve la pieza por todos sus lados, algo que no da una foto. Hay categorías como patrimonio e historia, arquitectura, animales o ciencia. "], "coolors": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Crear paletas de colores Diseñar materiales Trabajar el color en Plástica Dar coherencia a presentaciones Coolors es un generador de paletas de colores. Propone combinaciones que funcionan bien juntas y permite fijar los colores que te gustan para diseñar materiales con coherencia. Se van probando combinaciones hasta dar con una que convence. También saca colores de una imagen y comprueba el contraste para que un texto se lea bien. En clase se puede partir de un cuadro y comentar sus colores. "], "cervantes": ["bancos-de-recursos", ["I", "P", "S"], 1, "Imágenes y multimedia", "Buscar textos literarios Conocer la vida de los autores Preparar lecturas para clase Consultar prensa histórica La Biblioteca Virtual Miguel de Cervantes es un centro de Humanidades Digitales de la Universidad de Alicante. Reúne obras, biografías y portales de autores, con áreas de literatura, historia, lengua y literatura infantil y juvenil. Se busca por título, autor o contenido. Entre sus materiales hay también cronologías para situar a un autor. En clase se puede proyectar un fragmento o pasar el enlace de la obra. "], "intef": ["bancos-de-recursos", ["I", "P", "S"], 1, "Formación e inspiración", "Formarse Mejorar la competencia digital Buscar recursos Conocer proyectos educativos El INTEF es el Instituto Nacional de Tecnologías Educativas y de Formación del Profesorado. Ofrece cursos de formación, recursos educativos y el marco de referencia de la competencia digital docente. Desde su web se llega a Procomún, los materiales del CEDEC, el Observatorio de Tecnología Educativa, AseguraTIC y eXeLearning. Reúne también experiencias de centros que sirven de ejemplo a otros docentes. "], "educagob": ["bancos-de-recursos", ["I", "P", "S"], 1, "Formación e inspiración", "Consultar el currículo Consultar la normativa Buscar recursos Preparar la programación Educagob es el portal del Ministerio de Educación con información sobre el currículo, la normativa y recursos para el profesorado de todas las etapas. Cada materia tiene su página con el desarrollo, las competencias específicas y los criterios de evaluación. Es el currículo básico estatal: después hay que mirar el de tu comunidad. También explica cómo se organiza el sistema educativo. "], "edu30": ["bancos-de-recursos", ["I", "P", "S"], 1, "Formación e inspiración", "Inspirarse Descubrir herramientas Conocer experiencias de otros docentes Estar al día Educación 3.0 es una revista sobre innovación educativa, tecnología y recursos para el aula, con experiencias de docentes y recopilaciones de herramientas. Se lee como una revista en línea: noticias, artículos y prácticas contadas desde el centro. Sirve para ver cómo han llevado otros una idea a clase y decidir si encaja con tu grupo. También puede dar pie a una conversación en el claustro o en el departamento. "], "profeprod": ["bancos-de-recursos", ["I", "P", "S"], 1, "Formación e inspiración", "Aprender a usar la IA Usar plantillas de prompts Formarse Ahorrar tiempo Profesor Productivo es el proyecto de Guillermo Antón sobre inteligencia artificial para docentes. Ofrece formaciones, libros y material descargable, como plantillas de prompts y presentaciones. También tiene un blog con artículos sobre herramientas y técnicas de organización aplicadas a las tareas docentes. Puedes empezar por una plantilla, adaptarla a tu materia y revisar lo que devuelve la IA. "], "rosaliarte": ["bancos-de-recursos", ["I", "P", "S"], 1, "Formación e inspiración", "Inspirarse Descubrir herramientas Conocer experiencias de aula Trabajar con móviles El blog de Rosa Liarte, profesora de Geografía e Historia, comparte experiencias y recursos sobre tecnología y aprendizaje móvil en el aula. Hay guías sobre aplicaciones para crear materiales, evaluar y organizar el curso, también con inteligencia artificial. Las entradas se dirigen al profesorado y tratan asuntos del día a día, como las tutorías con las familias. Además del blog, tiene un pódcast y un libro. "], "academiaplay": ["bancos-de-recursos", ["I", "P", "S"], 1, "Formación e inspiración", "Introducir un tema Repasar Trabajar con aula invertida Motivar Academia Play es un canal de divulgación en vídeo sobre Historia, Arte y Geografía, que también trata temas de actualidad. Sus vídeos animados sirven para introducir o repasar un tema. Su web los ordena por materias y tiene además un curso de Historia de España. En clase se suele proyectar uno con dos o tres preguntas que el alumnado contesta mientras lo ve. Conviene verlo antes entero para decidir dónde parar. "]}};
